"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[6756],{9648(e){e.exports=JSON.parse('{"title":"undefined\ub294 JS\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ud45c\ud604\ub418\ub294\uac00","date":"2024-07-11","coverUrl":null,"html":"<h2 data-notion-block-id=\\"7f902894-a179-47df-8a5e-cccaab40b6d8\\" id=\\"7f902894-a179-47df-8a5e-cccaab40b6d8\\">undefined\ub294 JS\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ud45c\ud604\ub418\ub294\uac00</h2><a href=\\"https://mortoray.com/the-many-faces-of-undefined-in-javascript/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://mortoray.com/the-many-faces-of-undefined-in-javascript/</a><p data-notion-block-id=\\"65e87d25-e6de-4ae0-8eeb-667dfe192d0d\\"><b>\uc2ec\uc724\uc12d</b>: JS\ub294 \ud2b9\uc774\ud558\uac8c undefined\uc640 null\uc774\ub77c\ub294 \uc874\uc7ac\ud558\uc9c0 \uc54a\uc74c\uc744 \ub098\ud0c0\ub0b4\ub294 \uac12\uc774 \ub450 \uac1c\uac00 \uc788\uace0, \uac1d\uccb4\uc5d0\uc11c undefined\ub97c \ud560\ub2f9\ud558\ub294 \uac83\uacfc <code>delete</code>\ub97c \ud1b5\ud574 \uac1d\uccb4\uc758 \uac12\uc744 \uc9c0\uc6b0\ub294 \uac83\uc740 \ub2e4\ub974\uac8c \ub3d9\uc791\ud569\ub2c8\ub2e4. \uadf8\ub9ac\uace0 \ub3d9\uc801 \uc5b8\uc5b4\ub2f5\uac8c truthy\uc640 falsy \uac1c\ub150\uc744 \uac00\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc81c\uc5b4\ud560 \uc218 \uc788\ub294 \ucf54\ub4dc \ub0b4\uc5d0\uc11c\ub294 \ucd5c\ub300\ud55c \ud1b5\uc77c\ud558\uace0, \ub290\uc2a8\ud55c \ube44\uad50\ub97c \ud558\uc9c0 \ub9d0\uc544\ub2ec\ub77c\ub294 \uc774\uc57c\uae30\ub97c \ud569\ub2c8\ub2e4. undefined\uc640 null, \uadf8\ub9ac\uace0 truthy\uc640 falsy\ub97c \uc4f0\ub294 \ubc29\uc2dd\uc5d0 \ub300\ud574 \uc5b4\uc0c9\ud55c \ubd84\ub4e4\uc740 \uc77d\uc5b4\ubcf4\uc138\uc694!</p><h2 data-notion-block-id=\\"3c2ba461-b7a7-430c-b4b6-47a20f2106c3\\" id=\\"3c2ba461-b7a7-430c-b4b6-47a20f2106c3\\">CSS \uc2e0\uae30\uc220 \uc0ac\uc6a9\ud558\uae30(\ucee8\ud14c\uc774\ub108 \ucffc\ub9ac)</h2><a href=\\"https://web.dev/blog/how-to-use-container-queries-now?hl=ko\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://web.dev/blog/how-to-use-container-queries-now?hl=ko</a><p data-notion-block-id=\\"1bc5ecd5-23ed-4b1f-9722-5c44db628cb7\\"><b>\uc2ec\uc724\uc12d</b>: \ucee8\ud14c\uc774\ub108 \ucffc\ub9ac\uac00 \ubaa8\ub358 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \uc9c0\uc6d0\ud558\uac8c \ub41c\uc9c0 \uc624\ub798\ub418\uc5c8\uc9c0\ub9cc, <a href=\\"https://ones-to-watch.ethansup.net/news/post/b6be5023-1604-4d2d-9f86-d1888a427413#33710ab4-f781-493a-aaf6-1812739d7fd9\\"><code>contrast-color()</code></a><a href=\\"https://ones-to-watch.ethansup.net/news/post/b6be5023-1604-4d2d-9f86-d1888a427413#33710ab4-f781-493a-aaf6-1812739d7fd9\\">\uc5d0 \ub300\ud55c \uc0dd\uac01\ub4e4</a>\uc5d0\uc11c \ub098\uc654\ub4ef\uc774, \uc2e0 \uae30\uc220\uc774 \uac1c\ubc1c\uc790\ub4e4\uc774 \ubcf4\ud3b8\uc801\uc73c\ub85c \uc4f0\uae30\uae4c\uc9c0\ub294 \uc624\ub79c \uc2dc\uac04\uc774 \uac78\ub9bd\ub2c8\ub2e4. \uc774 \uae30\uc0ac\ub294 \ucee8\ud14c\uc774\ub108 \ucffc\ub9ac\ub97c \ub2e8\uacc4\uc801\uc73c\ub85c \uc811\uadfc\ud574\uc11c \uc801\uc6a9\ud558\uace0, CSS \ud3f4\ub9ac\ud544\uc5d0 \ub300\ud55c \uc811\uadfc\uacfc \ub808\uac70\uc2dc \ube0c\ub77c\uc6b0\uc800\ub97c \uc9c0\uc6d0\ud574\uc57c \ud558\ub294\uc9c0 \ub2e4\uc2dc \ud55c\ubc88 \uace0\uc0ac\ud574\ubcf4\uae38 \uc6d0\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc container query\ub97c \ub9ce\uc740 \uacf3\uc5d0 \uc801\uc751\ud558\ub824\uba74 \ubc18\uc751\ud615 \uc6f9\ud398\uc774\uc9c0\uc5d0 \ub300\ud55c \uc811\uadfc\uacfc \ub514\uc790\uc778 \ud639\uc740 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc744 \ud480\uc5b4\ub0b4\ub294 \ubc29\uc2dd \ub610\ud55c \ub3d9\uae30\ud654\ud574\uc57c \ud558\uae30 \ub54c\ubb38\uc5d0 \ub9ce\uc740 \uc2dc\uac04\uc774 \uc18c\uc694\ub420 \uac83 \uac19\ub124\uc694.</p><h2 data-notion-block-id=\\"537af57e-1528-49ad-b4f0-d84ef1805d8a\\" id=\\"537af57e-1528-49ad-b4f0-d84ef1805d8a\\">BBC Alt Text \uac00\uc774\ub4dc</h2><a href=\\"https://www.bbc.co.uk/gel/how-to-write-text-descriptions-alt-text\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.bbc.co.uk/gel/how-to-write-text-descriptions-alt-text</a><p data-notion-block-id=\\"8a3efde3-0540-4e0d-b765-065e90790675\\"><b>\uc2ec\uc724\uc12d</b>: \ub300\uccb4 \ud14d\uc2a4\ud2b8\ub97c \uc801\uc73c\uba74 \uc811\uadfc\uc131\uc5d0 \uc88b\ub2e4\ub294 \uc774\uc57c\uae30\ub294 \ub9ce\uc774\ub4e4 \ud558\ub294\ub370, \uc5b4\ub290 \uc774\ubbf8\uc9c0\uc5d0 \uc5b4\ub5a4 \ub300\uccb4 \ud14d\uc2a4\ud2b8\ub97c \ub123\uc5b4\uc57c \ud558\ub294\uc9c0 \uc544\ubb34\ub3c4 \uc54c\ub824\uc8fc\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. BBC\uc5d0\uc11c\ub294 \uc5b4\ub5bb\uac8c \uc801\ub294\uc9c0 \ubcf4\uace0 \uc5b4\ub5bb\uac8c \uc801\uc6a9\ud560\uae4c \uc0dd\uac01\ud574\ubcfc\ub9cc \ud569\ub2c8\ub2e4. \uad00\ub828\uc740 \uc5c6\uc9c0\ub9cc facebook\uc5d0\uc11c \uc0ac\uc9c4\uc5d0 \uc0ac\ub78c\uc774 \uc5b4\ub5a4 \ub3d9\uc791\uc744 \ud558\uace0 \uc788\ub294\uc9c0\uc5d0 \ub300\ud55c \uc124\uba85\uc774 \ubaa8\ub450 \ub4e4\uc5b4\uac00 \uc788\uc5b4\uc11c \uae5c\uc9dd \ub180\ub780 \uae30\uc5b5\uc774 \uc788\ub124\uc694.</p><h2 data-notion-block-id=\\"ac6bea7e-2bfd-4b67-be63-45c4aa20c804\\" id=\\"ac6bea7e-2bfd-4b67-be63-45c4aa20c804\\">RN \ubaa8\ub4c8\ub4e4\uc5d0 \ub300\ud55c \uac04\ub2e8\ud55c \uc18c\uac1c</h2><a href=\\"https://ospfranco.com/client-guide-to-react-native-modules/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ospfranco.com/client-guide-to-react-native-modules/</a><p data-notion-block-id=\\"03a6be9f-426f-4891-ad19-b55833381afd\\">\ucd5c\uadfc RN\uc740 \ub9ce\uc740 \ubaa8\ub4c8\uc774 \ub4f1\uc7a5\ud568\uc5d0 \ub530\ub77c \uc804\ubc18\uc801\uc778 \uc774\ud574\ub97c \ud558\uae30 \uc5b4\ub824\uc6b4 \ubd80\ubd84\uc774 \uc5c6\uc9c0 \uc54a\uc740\ub370, \uc774 \uae00\uc5d0\uc11c \ub300\ub7b5\uc801\uc73c\ub85c \uc18c\uac1c\ud574\uc8fc\ubbc0\ub85c, RN\uc744 \uc2dc\uc791\ud558\ub294 \ubd84\uc740 \ubcf4\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"969e40dc-655b-4138-ab9a-469e3d36729d\\" id=\\"969e40dc-655b-4138-ab9a-469e3d36729d\\">\ub4dc\ub798\uadf8 \uac00\ub2a5\ud55c Element\uc640 Snap \uad6c\ud604\ud558\uae30</h2><a href=\\"https://sinja.io/blog/framer-motion-drag-snap-points\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://sinja.io/blog/framer-motion-drag-snap-points</a><p data-notion-block-id=\\"ee83826b-a237-418f-b990-73a2d5074ca0\\">\ub4dc\ub798\uadf8 \uc564 \ub4dc\ub78d \uac00\ub2a5\ud55c \uc694\uc18c\uac00 \ud55c \uc9c0\uc810\uc5d0\uc11c \uba48\ucd94\uac8c \uad6c\ud604\ud558\uace0 \ucd94\uac00\ub85c \uad00\uc131\uae4c\uc9c0 \uad6c\ud604\ud558\ub294 \uacfc\uc815\uc744 \ub2f4\uc740 \uae00\uc785\ub2c8\ub2e4. <code>DOMMatrixReadOnly</code>\ub77c\ub294 \uc0c8\ub85c\uc6b4 API\uc640 \ud568\uaed8 \uac00\ubccd\uac8c \ubcfc\ub9cc\ud55c \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"abab33f9-933d-4c4e-8f2d-407ba448515d\\" id=\\"abab33f9-933d-4c4e-8f2d-407ba448515d\\">Mixed Content\uac00 \ubb54\ub370?</h2><a href=\\"https://frederikbraun.de/mixed-content.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frederikbraun.de/mixed-content.html</a><p data-notion-block-id=\\"5fca5220-2475-473b-8b9a-6d292cd5073e\\">\uc0dd\uc18c\ud558\uc9c0\ub9cc, Mixed Content\ub294 https\ub85c \ubd88\ub7ec\uc628 \ucee8\ud150\uce20\uc5d0\uc11c http \ucee8\ud150\uce20\ub97c \ud638\ucd9c\ud558\ub294 \ucee8\ud150\uce20\ub97c \uc9c0\uce6d\ud558\ub294 \ub9d0\uc785\ub2c8\ub2e4. CSP\ub97c \ud1b5\ud574\uc11c Mixed Content\ub85c\ubd80\ud130 \ubcf4\ud638\ud588\uc5c8\uace0, \uc774\uc81c \ubaa8\ub358 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \uc790\ub3d9\uc73c\ub85c HTTPS\ub85c \uc5c5\uadf8\ub808\uc774\ub4dc\ub41c\ub2e4\ub294 \uc18c\uc2dd\uc744 \uc804\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774 \uae00\uc744 \ud1b5\ud574 Mixed Content\uc758 \uc5ed\uc0ac\ub97c \uc54c \uc218 \uc788\uc73c\ub2c8 \ud765\ubbf8\ub86d\uac8c \ubcfc\ub9cc \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"0a5d6602-a6b1-466f-8070-36d75126051e\\" id=\\"0a5d6602-a6b1-466f-8070-36d75126051e\\">\uc0c8\ub85c\uc6b4 Set\uc758 \uba54\uc18c\ub4dc</h2><a href=\\"https://developer.mozilla.org/en-US/blog/javascript-set-methods/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://developer.mozilla.org/en-US/blog/javascript-set-methods/</a><p data-notion-block-id=\\"efd606e5-3ee3-4970-a52b-4bf0dd94741d\\">Set\uc758 \uc0c8\ub85c\uc6b4 \uba54\uc18c\ub4dc\uac00 \ubaa8\ub4e0 \ubaa8\ub358 \ube0c\ub77c\uc6b0\uc800\uc5d0 \uc801\uc6a9\ub418\uc5c8\ub2e4\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"a163b77e-0a2e-4893-8522-9aab937b813e\\" id=\\"a163b77e-0a2e-4893-8522-9aab937b813e\\">TypeScript \ucd94\ub860\uc740 \uc21c\uc11c\uc5d0 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4</h2><a href=\\"https://www.totaltypescript.com/property-order-matters\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.totaltypescript.com/property-order-matters</a><p data-notion-block-id=\\"5fbcd832-b67f-4487-89b3-540b60c0e5f3\\">TypeScript\uc5d0\uc11c \uac1d\uccb4\uc758 \ud504\ub85c\ud37c\ud2f0 \uc21c\uc11c\uac00 \ucd94\ub860\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4\ub294 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4.</p>"}')}}]);